def reviews():
    result = {}
    for line in REVIEW_TEXT.strip().splitlines():
        cells = line.split("|")
        assert len(cells) == 9, cells
        number = int(cells[0])
        assert number not in result
        result[number] = dict(zip(
            ["domains", "lot", "decisions", "judgment", "fixture", "steps", "forbidden", "oracle"], cells[1:]
        ))
    return result
